def right_angle_triangle(a, b, c):
    # Check if the input values are positive integers
    if all(isinstance(x, int) for x in [a, b, c]) and all(x > 0 for x in [a, b, c]):
        # Identify the largest number as the hypotenuse
        hypotenuse = max(a, b, c)
        legs = [x for x in [a, b, c] if x != hypotenuse]

        # Determine if the three sides can form a right-angled triangle
        if hypotenuse**2 == legs[0]**2 + legs[1]**2:
            # Return True if the sides can form a right-angled triangle, False otherwise
            return True
        else:
            return False
    else:
        return False

